// Auto-generated by scripts/build-freqs.js - English commonness of every
// legal guess word (Norvig's web-corpus unigram counts, log-scaled to
// 0..99, two digits per word in ALL_WORDS order). Do not edit by hand.
import { ALL_WORDS } from './words.js';

const DIGITS = '';

const table = new Map();
for (let i = 0; i < ALL_WORDS.length; i++) {
  table.set(ALL_WORDS[i], Number(DIGITS.slice(i * 2, i * 2 + 2)) / 99);
}

/** How common a word is in English: 0 (unseen or rare) to 1 (most common). */
export function commonness(word) {
  return table.get(word) || 0;
}
